  if(!/^[A-Za-z0-9_-]+$/.test(id))throw new Error('Identifiant de feuille invalide.');

  let email='';
  try{
    if(typeof cdqDefaultGoogleAccountV2299==='function')email=String(cdqDefaultGoogleAccountV2299()||'').trim().toLowerCase();
    if(!email)email=String(localStorage.getItem('cdqDefaultGoogleAccountV2299')||localStorage.getItem('cdqDefaultGoogleAccountV2294')||'').trim().toLowerCase();
  }catch(e){}

  const base='https://docs.google.com/spreadsheets/d/'+encodeURIComponent(id)+'/edit';
  const web=email
    ? base+'?usp=drivesdk&authuser='+encodeURIComponent(email)+'&login_hint='+encodeURIComponent(email)
    : base;

  let href=web;
  let target='_blank';

  if(/Android/i.test(navigator.userAgent||'')){
    if(email){
      // Compte par défaut actif : forcer explicitement Chrome depuis le vrai clic.
      href='intent://docs.google.com/spreadsheets/d/'+encodeURIComponent(id)+
        '/edit?usp=drivesdk&authuser='+encodeURIComponent(email)+
        '&login_hint='+encodeURIComponent(email)+
        '#Intent;scheme=https;package=com.android.chrome;'+
        'S.browser_fallback_url='+encodeURIComponent(web)+';end';
      target='_top';
    }else{
      // Sans compte par défaut, conserver le chemin Sheets natif historique.
      href='intent://docs.google.com/spreadsheets/d/'+encodeURIComponent(id)+
        '/edit#Intent;scheme=https;package=com.google.android.apps.docs.editors.sheets;'+
        'S.browser_fallback_url='+encodeURIComponent(base)+';end';
    }
  }

  const a=document.createElement('a');
  a.href=href;
  a.target=target;
  a.rel='noopener';
  a.style.display='none';
  document.body.appendChild(a);
  a.click();
  a.remove();

  // Repli Web uniquement si le lancement Chrome n'a réellement rien fait.
  if(email&&/Android/i.test(navigator.userAgent||'')){
    setTimeout(function(){
      if(document.visibilityState!=='visible')return;
      try{
        const b=document.createElement('a');
        b.href=web;b.target='_blank';b.rel='noopener';b.style.display='none';
        document.body.appendChild(b);b.click();b.remove();
